// lib/ui/raahi/benethe_stack.dart
import 'package:flutter/material.dart';

Widget buildBenetheCard(String cardSlug, String backgroundUrl) {
  return Stack(
    alignment: Alignment.topCenter,
    children: [
      // 1. The Imagery Background (Generated by Gemini - Midnight Heritage Aesthetic)
      Image.network(
        backgroundUrl, 
        fit: BoxFit.cover,
        width: double.infinity,
        height: double.infinity,
      ),

      // 2. The Typography Overlay (Renders perfectly over the Safe Zone)
      Positioned(
        top: 45, // Aligned for border-top padding bleeding space
        child: Column(
          children: [
            // The Latin Transliteration (e.g., "(Thari)")
            Text(
              getLatinName(cardSlug),
              style: TextStyle(
                color: Colors.white70,
                fontStyle: FontStyle.italic,
                fontSize: 14,
                letterSpacing: 1.2,
              ),
            ),
            const SizedBox(height: 10),
            // The 100% Accurate Noto Thaana (e.g., "ތަރި")
            // Locked to Gold (#F4B400) as per Visual Framework
            Text(
              getThaanaName(cardSlug),
              style: TextStyle(
                color: Color(0xFFF4B400),
                fontFamily: 'NotoThaana',
                fontWeight: FontWeight.w900,
                fontSize: 36,
                shadows: [
                  Shadow(
                    blurRadius: 10.0,
                    color: Colors.black.withOpacity(0.5),
                    offset: Offset(0, 2),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    ],
  );
}

// Placeholder functions for slug-to-name mapping
