  final map = {
    'fool': '(The Fool)',
    'magician': '(The Magician)',
    'high_priestess': '(The High Priestess)',
    'empress': '(The Empress)',
    'emperor': '(The Emperor)',
    'hierophant': '(The Hierophant)',
    'lovers': '(The Lovers)',
    'chariot': '(The Chariot)',
    'strength': '(Strength)',
    'hermit': '(The Hermit)',
    'wheel_of_fortune': '(Wheel of Fortune)',
    'justice': '(Justice)',
    'hanged_man': '(The Hanged Man)',
    'death': '(Death)',
    'temperance': '(Temperance)',
    'devil': '(The Devil)',
    'tower': '(The Tower)',
    'star': '(The Star)',
    'moon': '(The Moon)',
    'sun': '(The Sun)',
    'judgement': '(Judgement)',
    'world': '(The World)',
  };
  return map[slug.toLowerCase()] ?? '';
}

